import {native, syncNative, nativePermissions, nativeTest, nativeStatus, dismissNative} from './native.js';
import {iconNodes} from './icons.js';
import {TYPES,DAYS,today,addDays,occurs,done,validDate,validTime,monthExpenses,parseMoney,currency,blank,validateItem,validateData,overlap,budgetStatus} from './domain.js';
const $=s=>document.querySelector(s),KEY='meu-ritmo-lite:v1',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const THEME_LINK_KEY='meu-ritmo-lite:appearance-link',THEME_CACHE_KEY='meu-ritmo-lite:appearance-cache';
const THEME_URL='https://meuritmo.net/api/appearance-sync';
function applyAppearance(t){
 if(!t||!/^#[0-9a-f]{6}$/i.test(t.paper||'')||!/^#[0-9a-f]{6}$/i.test(t.ink||'')||!/^#[0-9a-f]{6}$/i.test(t.side||'')||!/^#[0-9a-f]{6}$/i.test(t.banner||'')||!/^#[0-9a-f]{6}$/i.test(t.accent||''))return false;
 const root=document.documentElement;
 root.dataset.liteTheme='linked';
 const values={'--paper':t.paper,'--ink':t.ink,'--muted':'color-mix(in srgb, '+t.ink+' 76%, '+t.paper+')','--line':'color-mix(in srgb, '+t.ink+' 18%, '+t.paper+')','--coral':t.accent,'--blue':t.accent,'--yellow':t.banner,'--accent':t.accent,'--green':t.banner,'--theme-banner':t.banner,'--theme-side':t.side};
 for(const [name,value]of Object.entries(values))root.style.setProperty(name,value);
 const dark=parseInt(t.paper.slice(1,3),16)<80&&parseInt(t.paper.slice(3,5),16)<80;
 root.dataset.liteDark=dark?'true':'false';
 document.querySelector('meta[name="theme-color"]')?.setAttribute('content',t.paper);
 return true;
}
try{applyAppearance(JSON.parse(localStorage.getItem(THEME_CACHE_KEY)||'null'));}catch{}
async function refreshAppearance(){
 let token;try{token=localStorage.getItem(THEME_LINK_KEY);}catch{return;}
 if(!token)return;
 try{
  const r=await fetch(THEME_URL,{headers:{Authorization:'Bearer '+token},cache:'no-store'});
  if(!r.ok){if(r.status===401){localStorage.removeItem(THEME_LINK_KEY);toast('A vinculação visual expirou. Vincule o Lite novamente.');}return;}
  const theme=await r.json();
  if(applyAppearance(theme))localStorage.setItem(THEME_CACHE_KEY,JSON.stringify(theme));
 }catch{/* Mantém o último tema recebido para uso offline. */}
}
refreshAppearance();
setInterval(refreshAppearance,15*60*1000);
window.addEventListener('online',refreshAppearance);
window.addEventListener('focus',refreshAppearance);
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(iconNodes[name]||iconNodes.note).map(([tag,attrs])=>`<${tag} ${Object.entries(attrs).filter(([k])=>k!=='key').map(([k,v])=>`${k}="${esc(v)}"`).join(' ')} />`).join('')}</svg>`;
const areas=[['hoje','Hoje','sun'],['agenda','Agenda','calendar'],['rotina','Rotina','routine'],['gastos','Gastos','wallet'],['notas','Notas','note'],['lembretes','Lembretes','bell'],['recados','Recados','message'],['alarmes','Alarmes','alarm']];
const types={task:['Tarefa','routine'],event:['Compromisso','calendar'],expense:['Gasto','wallet'],note:['Anotação','note'],reminder:['Lembrete','bell'],message:['Recado','message'],alarm:['Alarme','alarm']};
let data=blank(),area='hoje',date=today(),view='week',search='',filter='Todos',archived=false,storageError=false,undoState=null,audio=null,soundReady=false,alarmTimer=null,alarmCurrent=null,alertQueue=[],sw=null,saveTimer=null;
try{const raw=localStorage.getItem(KEY);if(raw)data=validateData(JSON.parse(raw));}catch{storageError=true}
function toast(message,undo=false){clearTimeout(toast.timer);$('#toast').innerHTML=`<span>${esc(message)}</span>${undo?'<button data-action="undo">Desfazer</button>':''}`;$('#toast').classList.add('show');toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),6500)}
function persist(next,{undo=false}={}){try{if(storageError)throw Error('Não foi possível abrir seus dados. Exporte o arquivo original em Dados antes de restaurar um backup.');const latest=localStorage.getItem(KEY);if(latest&&JSON.parse(latest).revision!==data.revision){throw Error('Outra aba alterou seus dados. Feche este formulário e recarregue a página antes de continuar.')}next=validateData(next);next.revision=data.revision+1;const raw=JSON.stringify(next);if(raw.length>2_000_000)throw Error('O armazenamento desta versão está cheio. Faça backup e arquive ou exclua itens antigos.');localStorage.setItem(KEY,raw);if(undo)undoState=structuredClone(data);data=next;syncNative(data);$('#saved').textContent='Salvo neste aparelho';return true}catch(e){$('#saved').textContent='Não foi salvo';toast(e.message||'Não foi possível salvar. Exporte um backup antes de fechar.');return false}}
function change(fn,options){const next=structuredClone(data);fn(next);return persist(next,options)}
const btn=(action,label,cls='secondary',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const short=d=>new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{day:'numeric',month:'short'});
const full=d=>new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'});
const activeItems=()=>data.items.filter(i=>!i.archived);
const daily=(type,d=date)=>activeItems().filter(i=>i.type===type&&occurs(i,d)&&!i.skip.includes(d));
function title(kicker,heading,description,action=''){const labels={hoje:['Um dia de cada vez<span class="coraltext">.</span>','O que importa hoje, sem perder de vista o resto.'],agenda:['Espaço para o que vem.','Seus compromissos, no tempo certo.'],rotina:['Do seu jeito, todo dia.','Uma rotina que se ajusta à vida. E não o contrário.'],gastos:['Suas contas, às claras.','Cada lançamento ajuda a entender seu mês.'],notas:['Ideias que ficam.','Do lembrete rápido à ideia que merece mais espaço.'],recados:['Recados por perto.','Um lugar para o que você não quer perder de vista.'],lembretes:['Para lembrar na hora certa.','Seus avisos, sem depender da memória.'],alarmes:['No horário combinado.','Som e aviso na tela enquanto o site estiver aberto.']};const [h,p]=labels[area];return `<div class="pageheading"><div><span class="eyebrow">${area==='hoje'?full(today()).toUpperCase():'MEU ESPAÇO / '+areas.find(a=>a[0]===area)[1].toUpperCase()}</span><h1>${h}</h1><p>${p}</p></div>${action||btn('quick',icon('plus',18)+'Adicionar item','primary')}</div>`}
function empty(type,text,description){return `<div class="empty"><span class="emptyicon">${icon(types[type][1],30)}</span><h3>${text}</h3><p>${description}</p>${btn('new','Criar '+types[type][0].toLowerCase()+' '+icon('plus',15),'secondary',`data-type="${type}"`)}</div>`}
function renderNav(){$('#arealabel').textContent=areas.find(a=>a[0]===area)?.[1]||'Hoje';const status=budgetStatus(data,today().slice(0,7));$('#navigation').innerHTML=areas.map(([id,label,ic])=>`<a href="#${id}" class="navitem ${area===id?'active':''}" ${area===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='hoje'?'<span class="navdot"></span>':''}${id==='gastos'&&status.over?`<span class="navdot ${status.reviewed?'reviewed':''}" aria-label="Orçamento excedido"></span>`:''}</a>`).join('');$('#bottomnav').innerHTML=[...areas.filter(a=>['hoje','agenda','gastos','rotina'].includes(a[0])),['mais','Mais','more']].map(([id,label,ic])=>id==='mais'?`<button data-action="more" class="${['notas','lembretes','recados','alarmes'].includes(area)?'active':''}">${icon(ic)}<span>${label}</span></button>`:`<a href="#${id}" ${area===id?'aria-current="page"':''} class="${area===id?'active':''}">${icon(ic)}<span>${label}</span></a>`).join('')}
function row(i,d=date){const isdone=done(i,d);return `<div class="taskrow ${isdone?'completed':''}"><button class="checkbox ${isdone?'checked':''}" data-action="done" data-id="${esc(i.id)}" data-date="${d}" aria-label="${isdone?'Reabrir':'Concluir'} ${esc(i.title)}" aria-pressed="${isdone}">${isdone?icon('check',13):''}</button><button class="tasktitle" data-action="edit" data-id="${esc(i.id)}">${esc(i.title)}<small>${i.time?esc(i.time):'Sem horário'}${i.habit?' · hábito':''}${i.repeat!=='none'?' · recorrente':''}</small></button><button class="iconbtn subtle" data-action="down" data-id="${esc(i.id)}" aria-label="Mover para baixo ${esc(i.title)}">${icon('chevron',15)}</button><button class="iconbtn subtle" data-action="postpone" data-id="${esc(i.id)}" data-date="${d}" aria-label="Adiar ${esc(i.title)}">${icon('arrow',15)}</button></div>`}
function flower(){return `<svg class="flower" viewBox="0 0 200 200" aria-hidden="true"><g fill="#ef795f">${[0,45,90,135,180,225,270,315].map(a=>`<ellipse cx="100" cy="55" rx="24" ry="40" transform="rotate(${a} 100 100)"/>`).join('')}<circle cx="100" cy="100" r="32" fill="#f4cf59"/><path d="M86 101q14 16 28 0" fill="none" stroke="#282d29" stroke-width="3" stroke-linecap="round"/><circle cx="89" cy="90" r="3" fill="#282d29"/><circle cx="111" cy="90" r="3" fill="#282d29"/></g></svg>`}
function sunArt(){return `<div class="dayart"><span class="artcircle"></span>${flower()}<svg viewBox="0 0 190 130" aria-hidden="true"><path d="M5 105C60 125 64 15 100 35S90 110 185 85" fill="none" stroke="#354f9e" stroke-width="3"/><path d="m175 74 12 12-15 8" fill="none" stroke="#354f9e" stroke-width="3"/></svg></div>`}
function financeContent(bs){return `<div class="financecontent budget-${bs.over?(bs.reviewed?'reviewed':'over'):'within'}"><div class="moneylarge">${currency(bs.total)}</div><p class="muted">${bs.budget?'de '+currency(bs.budget)+' planejados':'Defina um orçamento para acompanhar o mês.'}</p><div class="progress"><i style="width:${bs.budget?Math.min(100,bs.total/bs.budget*100):0}%"></i></div><div class="budgetbalance"><span>${bs.budget?(bs.over?'Acima do orçamento':'Ainda disponível'):'Orçamento do mês'}</span><strong>${bs.budget?currency(Math.abs(bs.balance)):'Não definido'}</strong></div>${bs.over?`<div class="budgetalert" role="status"><span class="budgetindicator"></span><div><strong>${bs.reviewed?'Excesso revisado':'Seu orçamento precisa de revisão'}</strong><p>${bs.reviewed?'O motivo foi registrado. O gasto continua acima do planejado.':'Você passou '+currency(-bs.balance)+' do que planejou. Registre o motivo ou ajuste seu orçamento.'}</p>${btn('review',bs.reviewed?'Ver ou editar justificativa':'Revisar excesso','textbutton')}</div></div>`:''}</div>`}
function renderToday(){const d=today(),tasks=daily('task',d),events=daily('event',d).sort((a,b)=>a.time.localeCompare(b.time)),bs=budgetStatus(data,d.slice(0,7)),notes=activeItems().filter(i=>['note','message'].includes(i.type)&&i.pinned).slice(0,1),alerts=[...daily('reminder',d),...daily('alarm',d)].filter(i=>i.enabled&&!done(i,d)).sort((a,b)=>a.time.localeCompare(b.time)),resolved=tasks.filter(i=>done(i,d)).length;return title('', '', '')+`<section class="daybanner"><div><span class="eyebrow">O DIA ESTÁ EM MOVIMENTO</span><h2>${tasks.length?resolved+' de '+tasks.length+' tarefas resolvidas.':'Seu dia começa por aqui.'}</h2><p>${tasks.length?'Você pode ajustar os planos pelo caminho.':'Adicione um compromisso, uma conta ou algo para fazer.'}</p><div class="dayticks">${Array.from({length:14},(_,i)=>`<span class="${i<resolved/Math.max(tasks.length,1)*14?'filled':''}"></span>`).join('')}</div><button class="dayreviewlink" data-action="dayreview">Passar o dia a limpo ${icon('arrow',14)}</button></div>${sunArt()}</section><div class="todaygrid"><section class="todayleft"><div class="sectionheading"><h2>Na sua lista <span>${tasks.length-resolved}</span></h2><a href="#rotina">Ver rotina ${icon('up',15)}</a></div>${tasks.length?tasks.map(i=>row(i,d)).join(''):`<div class="emptycompact">${icon('routine',24)}<p>O que você quer resolver hoje?</p>${btn('new','Adicionar primeira tarefa '+icon('plus',15),'textbutton','data-type="task"')}</div>`}<button class="addinline" data-action="new" data-type="task">${icon('plus',16)} Adicionar uma tarefa</button><div class="sectionheading agendaheading"><h2>O que vem a seguir</h2><a href="#agenda">Abrir agenda ${icon('up',15)}</a></div>${events.length?events.slice(0,3).map(i=>`<button class="eventrow ${i.color}" data-action="edit" data-id="${esc(i.id)}"><div class="eventtime">${esc(i.time)}<small>${esc(i.end)}</small></div><div class="eventdetail"><h3>${esc(i.title)}</h3><p>${esc(i.body||'Compromisso pessoal')}</p></div>${icon('up',18)}</button>`).join(''):`<div class="emptycompact"><p>A agenda está livre por aqui.</p>${btn('new','Criar um compromisso '+icon('plus',15),'textbutton','data-type="event"')}</div>`}${alerts.length?`<div class="remindercard">${icon('bell',18)}<div><small>PARA NÃO PASSAR BATIDO</small>${alerts.map(i=>`<button data-action="edit" data-id="${esc(i.id)}">${esc(i.title)} <span>${esc(i.time)}</span></button>`).join('')}</div></div>`:''}</section><aside class="todayright"><section class="financebox status-${bs.over?(bs.reviewed?'reviewed':'over'):'within'}"><div class="sectionheading"><h2>Seu mês em números</h2>${icon('wallet',18)}</div><span class="eyebrow">${new Date().toLocaleDateString('pt-BR',{month:'long'})} · GASTOS</span>${financeContent(bs)}<a class="financeopen" href="#gastos">Olhar meus gastos ${icon('up',16)}</a></section><div class="sectionheading"><h2>Por perto ${icon('pin',16)}</h2><a href="#notas">Ver notas ${icon('up',15)}</a></div>${notes.length?notes.map(noteCard).join(''):`<button class="blanknote" data-action="new" data-type="note">${icon('note',25)}<span>Um espaço para aquela ideia.</span>${icon('plus',18)}</button>`}</aside></div><div class="localnote">${icon('leaf',16)}<p>Seus registros ficam neste aparelho. <button data-action="settings">Exporte um backup</button> para guardar uma cópia ou trocar de aparelho.</p></div>`}
function datebar(){return `<div class="toolbar datebar"><div class="datecontrols"><button class="iconbtn" data-action="prev" aria-label="Período anterior">‹</button><h2>${new Date(date+'T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h2><button class="iconbtn" data-action="next" aria-label="Próximo período">›</button>${btn('today','Hoje','textbutton')}</div><div class="segmented" aria-label="Visualização da agenda">${[['day','Dia'],['week','Semana'],['month','Mês']].map(([v,t])=>`<button data-action="view" data-view="${v}" class="${view===v?'active':''}" aria-pressed="${view===v}">${t}</button>`).join('')}</div><input aria-label="Ir para data" type="date" id="agendadate" value="${date}"></div>`}
function dayEvents(d){return daily('event',d).sort((a,b)=>a.time.localeCompare(b.time))}
function renderAgenda(){let content='';if(view==='month'){const start=date.slice(0,7)+'-01',offset=new Date(start+'T12:00:00').getDay(),first=addDays(start,-offset);content=`<div class="monthgrid">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(s=>`<span class="weekday">${s}</span>`).join('')}${Array.from({length:42},(_,k)=>{const d=addDays(first,k),events=dayEvents(d);return `<button class="monthday ${d===today()?'istoday':''} ${d.slice(0,7)!==date.slice(0,7)?'faded':''}" data-action="day" data-date="${d}"><span>${Number(d.slice(8))}</span>${events.slice(0,2).map(i=>`<small class="eventchip ${i.color}">${esc(i.time)} ${esc(i.title)}</small>`).join('')}${events.length>2?`<small>+${events.length-2} compromissos</small>`:''}</button>`}).join('')}</div>`}else if(view==='week'){const first=addDays(date,-((new Date(date+'T12:00:00').getDay()+6)%7));content=`<div class="weekgrid">${Array.from({length:7},(_,k)=>{const d=addDays(first,k),events=dayEvents(d);return `<section class="weekdaycol ${d===today()?'istoday':''}"><button class="daylabel" data-action="day" data-date="${d}"><span>${DAYS[new Date(d+'T12:00:00').getDay()]}</span><strong>${Number(d.slice(8))}</strong></button>${events.map(i=>`<button class="weekevent ${i.color}" data-action="edit" data-id="${esc(i.id)}"><time>${esc(i.time)} — ${esc(i.end)}</time><strong>${esc(i.title)}</strong></button>`).join('')}${btn('new',icon('plus',16),'addslot',`data-type="event" data-date="${d}" aria-label="Criar compromisso em ${short(d)}"`)}</section>`}).join('')}</div>`}else{const events=dayEvents(date);content=events.length?`<div class="dayevents">${events.map(i=>`<button class="dayevent ${i.color}" data-action="edit" data-id="${esc(i.id)}"><time>${i.time}<small>${i.end}</small></time><div><h3>${esc(i.title)}</h3><p>${esc(i.body)}</p>${i.repeat!=='none'?'<small>Compromisso recorrente</small>':''}</div>${icon('edit',16)}</button>`).join('')}</div>`:empty('event','Ainda não há compromissos nesta data.','Marque o primeiro e veja seus horários reunidos aqui.')}return title('UM LUGAR PARA CADA HORÁRIO.','Agenda','Compromissos claros, sem apertar o dia.',btn('new',icon('plus',16)+' Novo compromisso','primary','data-type="event"'))+datebar()+content}
function renderRoutine(){const list=daily('task');return title('COM HORÁRIO OU NO TEMPO QUE DER.','Rotina','Tarefas e hábitos, sem contagem de sequências.',btn('new',icon('plus',16)+' Nova tarefa','primary','data-type="task"'))+`<div class="toolbar"><label>Dia <input type="date" id="routinedate" value="${date}"></label>${btn('today','Voltar para hoje','textbutton')}</div><div class="routinedays">${Array.from({length:7},(_,k)=>{const d=addDays(date,-((new Date(date+'T12:00:00').getDay()+6)%7)+k);return `<button data-action="routineday" data-date="${d}" aria-pressed="${date===d}" class="${date===d?'active':''}"><span>${DAYS[new Date(d+'T12:00:00').getDay()]}</span><strong>${Number(d.slice(8))}</strong></button>`}).join('')}</div><div class="routinebar"><button data-action="routineprev">← Semana anterior</button><h2>${full(date)}</h2><button data-action="routinenext">Próxima semana →</button></div>${list.length?['Com horário','A qualquer momento'].map((label,k)=>`<section class="section routinegroup"><div class="sectionheading"><h2>${label}</h2>${btn('new',icon('plus',16)+'Tarefa','textbutton','data-type="task"')}</div>${list.filter(i=>k?!i.time:!!i.time).map(i=>`<div class="reorderrow">${row(i)}<div><button data-action="up" data-id="${esc(i.id)}" aria-label="Mover ${esc(i.title)} para cima">↑</button><button data-action="down" data-id="${esc(i.id)}" aria-label="Mover ${esc(i.title)} para baixo">↓</button></div></div>`).join('')||'<p class="muted">Nenhuma tarefa neste grupo.</p>'}</section>`).join(''):empty('task','Sua rotina ainda está em branco.','Crie uma tarefa ou escolha dias da semana para um hábito.')}`}
function renderExpenses(){const month=date.slice(0,7),bs=budgetStatus(data,month),all=monthExpenses(data.items,month),categories=['Todos','Alimentação','Casa','Transporte','Saúde','Lazer','Educação','Outros'],list=all.filter(i=>(filter==='Todos'||i.category===filter)&&(!search||i.title.toLowerCase().includes(search.toLowerCase())));return title('','','',btn('new',icon('plus',18)+'Novo gasto','primary','data-type="expense"'))+`<div class="toolbar"><label>Mês <input type="month" id="expensemonth" value="${month}"></label><label>Categoria<select id="categoryfilter">${categories.map(c=>`<option ${c===filter?'selected':''}>${c}</option>`).join('')}</select></label>${btn('budget','Ajustar orçamento '+icon('edit',15),'textbutton')}</div><div class="explainline"><span>Registre o que saiu do seu bolso. Recorrências entram no total do mês como lançamentos previstos.</span>${btn('guide','Como funciona','textbutton')}</div><div class="financesummary"><div>${financeContent(bs)}</div><div><span class="eyebrow">DISTRIBUIÇÃO DO MÊS</span>${[...new Set(all.map(i=>i.category))].map(c=>{const n=all.filter(i=>i.category===c).reduce((s,i)=>s+i.amount,0);return `<div class="categorybar"><div><span>${c}</span><strong>${currency(n)}</strong></div><div class="progress"><i style="width:${bs.total?n/bs.total*100:0}%"></i></div></div>`}).join('')}${!all.length?'<p class="muted">Seu primeiro gasto vai aparecer aqui.</p>':''}</div></div><div class="sectionheading"><h2>Lançamentos</h2>${btn('backup',icon('download',15)+'Exportar dados','textbutton')}</div><label class="searchfield expense-search">${icon('search',16)}<input id="search" type="search" placeholder="Buscar gasto" aria-label="Buscar gasto" value="${esc(search)}"></label>${list.length?`<div class="expensetable normalexpenses">${list.map(i=>`<button class="expenserow" data-action="edit" data-id="${esc(i.id)}"><span class="expenseicon">${icon('wallet',18)}</span><div><strong>${esc(i.title)}</strong><small>${i.category} · ${new Date(i.occurrence+'T12:00:00').toLocaleDateString('pt-BR')}${i.repeat!=='none'?' · recorrente':''}</small></div><strong>${currency(i.amount)}</strong>${icon('edit',15)}</button>`).join('')}</div>`:empty('expense','Nenhum lançamento neste filtro.','Registre um gasto para acompanhar o mês.')}`}
function noteCard(i){return `<article class="note ${i.color}"><div class="notehead"><small>${esc(i.tags||(i.type==='message'?'RECADO':'ANOTAÇÃO'))}</small><button class="iconbtn" data-action="pin" data-id="${esc(i.id)}" aria-pressed="${i.pinned}" aria-label="${i.pinned?'Desafixar':'Fixar'} ${esc(i.title)}">${i.pinned?icon('pin',16).replace('fill="none"','fill="currentColor"'):icon('pin',16)}</button></div><button class="notecontent" data-action="note" data-id="${esc(i.id)}"><h3>${esc(i.title)}</h3><p>${esc(i.body||'Clique para escrever…')}</p></button><footer><span>${short(i.date)}</span><button class="iconbtn" data-action="archive" data-id="${esc(i.id)}" aria-label="${i.archived?'Restaurar':'Arquivar'} ${esc(i.title)}">${icon('archive',15)}</button></footer></article>`}
function renderNotes(type){const isMessage=type==='message',items=data.items.filter(i=>i.type===type&&i.archived===archived&&(!search||(i.title+' '+i.body+' '+i.tags).toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>Number(b.pinned)-Number(a.pinned));return title(isMessage?'UM RECADO PARA VOCÊ MESMO.':'IDEIAS COM ENDEREÇO. ',isMessage?'Recados':'Notas',isMessage?'Deixe à vista o que não quer perder no meio do dia.':'Escreva livremente ou transforme linhas em uma lista.',btn('new',icon('plus',16)+(isMessage?' Novo recado':' Nova nota'),'primary',`data-type="${type}"`))+`<div class="toolbar listfilters"><label class="searchfield">${icon('search',16)}<input id="search" type="search" placeholder="Buscar por texto ou etiqueta" aria-label="Buscar ${isMessage?'recados':'notas'}" value="${esc(search)}"></label><button data-action="archived" class="smallbutton" aria-pressed="${archived}">${archived?'Voltar às notas':'Arquivadas'}</button><span class="muted">Até 3 itens fixados · ${data.items.filter(i=>i.pinned&&!i.archived).length}/3</span></div>${items.length?`<div class="notesgrid noteboard">${items.map(noteCard).join('')}</div>`:empty(type,archived?'Nada arquivado por aqui.':isMessage?'Um recado também organiza o dia.':'Uma ideia não precisa esperar.',isMessage?'Um endereço, uma observação, algo que você quer ter por perto.':'Crie sua primeira nota. Sem precisar escolher uma pasta.')}`}
function renderNativeAlerts(type){const alarm=type==='alarm',status=nativeStatus(),items=activeItems().filter(i=>i.type===type).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time)),scheduled=status.scheduled||[];return title('','','',btn('new',icon('plus',18)+(alarm?'Novo alarme':'Novo lembrete'),'primary',`data-type="${type}"`))+`<section class="channelnotice"><div>${icon(alarm?'alarm':'bell',26)}<h2>${alarm?'Cada alarme tem seu horário no Android.':'Aviso simples ou alarme sonoro: você escolhe.'}</h2><p>Os agendamentos usam o sistema do celular, inclusive com o aplicativo fechado. Exigem as permissões abaixo. Não há disparo com o aparelho desligado ou após parada forçada; limites de bateria, volume e Não perturbe podem afetar o aviso. Ao reiniciar, os horários são restaurados.</p></div><div><strong>Notificações: ${status.notifications?'permitidas':'não permitidas'}</strong><strong>Alarmes exatos: ${status.exact?'permitidos':'não permitidos'}</strong>${btn('nativepermissions','Gerenciar permissões','secondary')}${btn('nativetest','Testar alarme em 10 segundos','secondary')}</div></section><div class="sectionheading"><h2>${scheduled.length} próximos agendamentos no Android</h2>${btn('nativestatus','Atualizar estado','textbutton')}</div>${(status.active||[]).length?`<section class="nativeactive" role="status"><h2>Alarmes em execução</h2>${status.active.map(a=>`<div><strong>${esc(a.title)}</strong>${btn('nativestop','Parar','secondary',`data-id="${esc(a.id)}"`)}${btn('nativesnooze','Adiar 10 min','secondary',`data-id="${esc(a.id)}"`)}</div>`).join('')}</section>`:''}${items.length?`<div class="alertlist">${items.map(i=>{const entry=scheduled.find(s=>s.id===i.id);return `<div class="alertrow"><span class="alerttime">${i.time||'Sem horário'}</span><button class="rowbody" data-action="edit" data-id="${esc(i.id)}"><strong>${esc(i.title)}</strong><span>${i.type==='alarm'||i.soundAlarm?'Alarme sonoro':'Notificação sem alarme sonoro'} · ${!i.enabled?'pausado':entry?'agendado: '+new Date(entry.at).toLocaleString('pt-BR'):'sem próximo disparo autorizado'}</span></button><button class="toggle ${i.enabled?'on':''}" data-action="enabled" data-id="${esc(i.id)}" role="switch" aria-checked="${i.enabled}" aria-label="Ativar ${esc(i.title)}"><span></span></button></div>`}).join('')}</div>`:empty(type,alarm?'Nenhum alarme criado.':'O que você precisa lembrar?',alarm?'Crie um horário e teste as permissões do celular.':'Ative o alarme sonoro no formulário se quiser que ele toque.')}`}
function renderAlerts(type){if(native)return renderNativeAlerts(type);const alarm=type==='alarm',items=activeItems().filter(i=>i.type===type).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time));return title(alarm?'UM HORÁRIO PARA CHAMAR SUA ATENÇÃO.':'PARA LEMBRAR NA HORA CERTA.',alarm?'Alarmes':'Lembretes',alarm?'Som e aviso na tela enquanto este site estiver aberto.':'Avisos únicos ou recorrentes, sem depender da memória.',btn('new',icon('plus',16)+(alarm?' Novo alarme':' Novo lembrete'),'primary',`data-type="${type}"`))+`<section class="channelnotice"><div>${icon(alarm?'alarm':'bell',26)}<h2>${alarm?'Alarmes sonoros precisam da página aberta.':'Você escolhe como receber o aviso.'}</h2><p>${alarm?'O dispositivo deve estar ativo e o som precisa ser liberado nesta sessão. Não toca com o site fechado, aparelho desligado ou suspenso.':'Os lembretes são verificados enquanto a página está aberta. Notificações do sistema dependem da permissão e do suporte do navegador. Não há agendamento no servidor.'}</p></div><div>${alarm?`<strong>${soundReady?'Som liberado nesta sessão':'Som ainda não liberado'}</strong>${btn('sound',soundReady?'Testar som':'Liberar e testar som','secondary')}`:`<strong>${'Notification'in window?Notification.permission==='granted'?'Permissão concedida':Notification.permission==='denied'?'Permissão bloqueada no navegador':'Permissão ainda não solicitada':'Navegador sem suporte'}</strong>${btn('notification','Configurar e testar notificação','secondary')}`}</div></section>${items.length?`<div class="alertlist">${items.map(i=>`<div class="alertrow"><span class="alerttime">${i.time||'Sem horário'}</span><button class="rowbody" data-action="edit" data-id="${esc(i.id)}"><strong>${esc(i.title)}</strong><span>${short(i.date)}${i.repeat!=='none'?' · '+({daily:'Diário',weekly:'Semanal',monthly:'Mensal'}[i.repeat]):''}${!i.enabled?' · pausado':''}</span></button><button class="toggle ${i.enabled?'on':''}" data-action="enabled" data-id="${esc(i.id)}" role="switch" aria-checked="${i.enabled}" aria-label="Ativar ${esc(i.title)}"><span></span></button></div>`).join('')}</div>`:empty(type,alarm?'Nenhum alarme programado.':'O que você precisa lembrar?',alarm?'Escolha um horário e teste o som antes de contar com ele.':'Adicione um aviso com data e, se quiser, horário.')}`}
