function modal(title,body,cls=''){flushNote();clearTimeout(saveTimer);const dialog=$('#dialog');dialog.className=cls;dialog.innerHTML=`<div class="dialoghead"><h2 id="dialogtitle">${title}</h2><button class="iconbutton" data-action="close" aria-label="Fechar janela">${icon('close',21)}</button></div>${body}`;if(!dialog.open)dialog.showModal();setTimeout(()=>dialog.querySelector('input:not([type=checkbox]),textarea,button')?.focus(),0)}
