function newItem(type,day=date){return {id:crypto.randomUUID(),type,title:'',date:['note','message'].includes(type)?today():day,time:'',end:'',amount:0,category:'Outros',body:'',repeat:'none',days:[],completed:[],skip:[],checked:[],color:'blue',tags:'',pinned:false,archived:false,notify:false,enabled:true,list:false,habit:false,soundAlarm:false}}
