function editor(type,id,day){const item=id?data.items.find(i=>i.id===id):newItem(type,day||date);if(!item)return;const i=structuredClone(item),note=['note','message'].includes(i.type),alarm=i.type==='alarm';modal((id?'Editar ':['task','note'].includes(i.type)?'Nova ':'Novo ')+types[i.type][0].toLowerCase(),`<form id="itemform" data-id="${esc(i.id)}" data-type="${i.type}"><p class="formerror" id="formerror" role="alert" hidden></p><label>${i.type==='expense'?'Descrição':'Título'}<input name="title" required maxlength="160" value="${esc(i.title)}" placeholder="${({task:'Ex.: separar documentos',event:'Ex.: consulta às 15h',expense:'Ex.: mercado da semana',note:'Dê um nome à ideia',message:'O que você quer deixar à vista?',alarm:'Ex.: sair para a consulta',reminder:'Ex.: pagar a conta de luz'})[i.type]}"></label>${i.type==='expense'?`<div class="formgrid"><label>Valor (R$)<input name="amount" inputmode="decimal" required value="${i.amount?(i.amount/100).toFixed(2).replace('.',','):''}" placeholder="0,00"></label><label>Categoria<select name="category">${['Alimentação','Casa','Transporte','Saúde','Lazer','Educação','Outros'].map(c=>`<option ${i.category===c?'selected':''}>${c}</option>`).join('')}</select></label></div>`:''}${!note?`<div class="formgrid"><label>Data<input name="date" type="date" required value="${i.date}"></label>${i.type!=='expense'?`<label>${i.type==='task'?'Horário (opcional)':'Horário'}<input name="time" type="time" ${i.type==='event'||alarm?'required':''} value="${i.time}"></label>`:''}${i.type==='event'?`<label>Término<input name="end" type="time" required value="${i.end}"></label>`:''}</div>`:''}<label>${note?'Conteúdo':'Observações (opcional)'}<textarea name="body" rows="${note?5:2}" maxlength="20000" placeholder="${note?'Pode começar por aqui. Uma linha de cada vez.':'Mais algum detalhe?'}">${esc(i.body)}</textarea></label>${note?`<label class="checkline"><input type="checkbox" name="list" ${i.list?'checked':''}>Transformar cada linha em uma caixa de seleção</label><label>Etiquetas (opcional)<input name="tags" maxlength="160" value="${esc(i.tags)}" placeholder="Ex.: casa, ideia, viagem"></label>`:''}${i.type==='task'?`<label class="checkline"><input name="habit" type="checkbox" ${i.habit?'checked':''}>É um hábito da minha rotina</label>`:''}${native&&i.type==='reminder'?`<label class="checkline"><input type="checkbox" name="soundAlarm" ${i.soundAlarm?'checked':''}>Tocar um alarme sonoro neste lembrete</label><p class="formhint">O aviso terá um agendamento próprio no Android. Exige notificações e permissão para alarmes.</p>`:''}<details ${i.repeat!=='none'?'open':''}><summary>${note?'Cor e destaque':'Repetição e opções'}</summary>${!note?`<label>Repetir<select name="repeat" id="repeat"><option value="none">Não repetir</option><option value="daily" ${i.repeat==='daily'?'selected':''}>Todos os dias</option><option value="weekly" ${i.repeat==='weekly'?'selected':''}>Dias da semana</option><option value="monthly" ${i.repeat==='monthly'?'selected':''}>Todo mês</option></select></label><fieldset id="weekdays" ${i.repeat==='weekly'?'':'hidden'}><legend>Em quais dias?</legend><div class="daychoices">${DAYS.map((d,k)=>`<label><input type="checkbox" name="days" value="${k}" ${i.days.includes(k)?'checked':''}><span>${d}</span></label>`).join('')}</div></fieldset>${['task','event'].includes(i.type)?`<label class="checkline"><input name="notify" type="checkbox" ${i.notify?'checked':''}>Mostrar aviso na tela no horário escolhido</label>`:''}`:''}<fieldset><legend>Cor</legend><div class="colorchoices">${[['blue','Azul'],['coral','Coral'],['yellow','Amarelo'],['pink','Rosa']].map(([c,t])=>`<label class="${c}"><input type="radio" name="color" value="${c}" ${i.color===c?'checked':''}>${t}</label>`).join('')}</div></fieldset>${note?`<label class="checkline"><input name="pinned" type="checkbox" ${i.pinned?'checked':''}>Fixar no topo (até 3 notas e recados)</label>`:''}</details>${id&&i.repeat!=='none'?'<p class="formhint">Alterações valem para toda a série. Adiar na rotina muda apenas a ocorrência daquele dia.</p>':''}${alarm?`<p class="formhint">${native?'Cada alarme é agendado no Android e pode tocar com o aplicativo fechado. Exige permissões; não toca com o aparelho desligado.':'O som só funciona com a página aberta e o dispositivo ativo. Libere o som na tela Alarmes.'}</p>`:''}${native&&id&&i.type==='event'?btn('calendar','Adicionar ao calendário do celular','secondary','type="button" data-id="'+esc(i.id)+'"'):''}<div class="dialogactions">${id?btn('delete','Excluir','danger',`type="button" data-id="${esc(i.id)}"`):'<span></span>'}<button type="submit" class="primary">${id?'Salvar alterações':'Adicionar '+types[i.type][0].toLowerCase()} ${icon('check',16)}</button></div></form>`);$('#itemform').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),next={...i,title:f.get('title')||'',body:f.get('body')||'',date:f.get('date')||i.date,time:f.get('time')||'',end:f.get('end')||'',amount:i.type==='expense'?parseMoney(f.get('amount')):0,category:f.get('category')||'Outros',repeat:f.get('repeat')||'none',days:f.getAll('days').map(Number),color:f.get('color')||'paper',tags:f.get('tags')||'',list:f.has('list'),pinned:f.has('pinned'),notify:f.has('notify'),habit:f.has('habit'),soundAlarm:f.has('soundAlarm')};validateItem(next);if(next.repeat==='weekly'&&!next.days.length)throw Error('Escolha pelo menos um dia da semana.');if(next.pinned&&!i.pinned&&data.items.filter(x=>x.pinned&&!x.archived).length>=3)throw Error('Você já tem três itens fixados. Desafixe um para deixar este à vista.');const conflicts=next.type==='event'?overlap(data.items,next):[];if(conflicts.length&&!confirm('Esse horário coincide com '+conflicts.map(x=>x.title).join(', ')+'. Salvar mesmo assim?'))return;if(change(d=>{const at=d.items.findIndex(x=>x.id===i.id);if(at<0)d.items.push(next);else d.items[at]=next})){close();toast(id?'Alterações salvas.':'Tudo anotado.');if(native&&(next.type==='alarm'||next.type==='reminder'||next.notify)&&next.time&&(!nativeStatus().exact||!nativeStatus().notifications))nativePermissions();}}catch(err){$('#formerror').hidden=false;$('#formerror').textContent=err.message;$('#formerror').focus()}}}
function openNote(id){const i=data.items.find(i=>i.id===id);if(!i)return;modal(esc(i.title),`<p class="formhint">Alterações são salvas automaticamente neste aparelho.</p><label>Conteúdo<textarea id="notebody" rows="8" maxlength="20000">${esc(i.body)}</textarea></label><p id="autosavestate" class="autosavestate" role="status">Salvo</p>${i.list?`<div class="notechecks">${i.body.split('\n').filter(s=>s.trim()).map((s,k)=>`<label class="checkline"><input type="checkbox" data-check="${k}" data-id="${esc(i.id)}" ${i.checked.includes(k)?'checked':''}>${esc(s)}</label>`).join('')}</div>`:''}<div class="noteconversions">${btn('convert','Criar tarefa','smallbutton',`data-id="${esc(i.id)}" data-type="task"`)}${btn('convert','Criar lembrete','smallbutton',`data-id="${esc(i.id)}" data-type="reminder"`)}</div><div class="dialogactions">${btn('edit','Editar detalhes','secondary',`data-id="${esc(i.id)}"`)}${btn('close','Concluir','primary')}</div>`);$('#notebody').oninput=e=>{const value=e.target.value;$('#autosavestate').textContent='Salvando…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>{saveTimer=null;const ok=change(d=>{const n=d.items.find(x=>x.id===id);n.body=value;n.checked=[]});$('#autosavestate').textContent=ok?'Salvo':'Não foi salvo. Copie o conteúdo antes de fechar.';if(ok&&i.list){const div=$('.notechecks');div.innerHTML=value.split('\n').filter(s=>s.trim()).map((s,k)=>`<label class="checkline"><input type="checkbox" data-check="${k}" data-id="${esc(id)}">${esc(s)}</label>`).join('')}},400)}}
function backup(raw=false){if(native){AndroidHost.backup(JSON.stringify(data));return;}const text=raw?localStorage.getItem(KEY)||JSON.stringify(data):JSON.stringify(data,null,2),blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`meu-ritmo-lite-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup preparado. Guarde o arquivo em um lugar seguro.')}
function reviewDay(){modal('Passar o dia a limpo',`<p class="dialogintro">Confira o que ficou para hoje e ajuste o que precisa ir para amanhã.</p>${daily('task',today()).map(i=>row(i,today())).join('')||'<p class="muted">Nenhuma tarefa para revisar hoje.</p>'}<p class="formhint">Gastos do mês: ${currency(budgetStatus(data,today().slice(0,7)).total)}. Você pode conferir os detalhes na área Gastos.</p>${btn('close','Concluir revisão','primary')}`);}
function settings(){modal('Seus dados, neste aparelho',`<div class="privacycard"><h3>Não há conta nem sincronização.</h3><p>Os registros ficam no armazenamento local do aplicativo neste aparelho, sem conta ou nuvem. Quem tiver acesso ao aplicativo desbloqueado poderá vê-los. Limpar os dados do aplicativo ou desinstalá-lo apaga os registros. Exporte backups regularmente.</p></div>${native?`<div class="privacycard"><h3>Permissões e alarmes do Android</h3><p>Veja os avisos agendados e controle as permissões do sistema.</p>${btn('nativepermissions','Gerenciar permissões','secondary')}</div>`:''}<div class="settingsrows"><div><h3>Aparência do Meu Ritmo</h3><p>O Lite acompanha o tema escolhido na sua conta do Meu Ritmo. Conecte uma vez e a aparência será atualizada quando houver internet. Os seus registros continuam neste aparelho.</p><form id="appearance-link-form"><label>Chave de vinculação<input name="appearanceToken" type="text" autocomplete="off" spellcheck="false" maxlength="64" minlength="64" pattern="[a-fA-F0-9]{64}" placeholder="Cole a chave gerada em Meu estilo" required></label><button class="secondary">Vincular aparência</button></form><button class="textbutton" data-action="unlinkappearance">Desvincular aparência</button><p class="formhint">Gere a chave no Meu Ritmo normal, em Meu estilo → Aparência. Não compartilhe a chave com outras pessoas.</p></div><div><h3>Guardar uma cópia</h3><p>O backup inclui gastos, agenda, rotina, notas e avisos.</p>${btn('backup',icon('download',16)+' Exportar backup','secondary')}</div><div><h3>Restaurar um backup</h3><p>Substitui os dados atuais após sua confirmação. Exporte uma cópia antes.</p>${btn('restore','Escolher arquivo JSON','secondary')}</div><div><h3>Começar de novo</h3><p>Apaga todos os registros deste aplicativo. O backup baixado permanece com você.</p>${btn('clear','Apagar meus dados locais','danger')}</div></div><p class="formhint">Versão Lite · ${data.items.length}/2.000 itens · sem planos, rastreamento ou integrações externas.</p>${btn('privacy','Privacidade e limites','textbutton')}`)}
function privacy(){modal('Privacidade e funcionamento',`<div class="legaltext"><h3>O que fica guardado</h3><p>Seus registros e preferências são salvos em armazenamento local. Não enviamos esses registros a um servidor, não pedimos nome ou e-mail e não há Google Analytics, anúncios ou pixels de rastreamento. O aplicativo não inclui rastreadores. Links externos abrem no navegador e seguem as políticas do respectivo serviço.</p><h3>O que o Lite não oferece</h3><p>Não há login, assinatura, comunidade, temas pagos, personalização de perfil ou armazenamento em nuvem. Este espaço é independente do Meu Ritmo original.</p><h3>Avisos e alarmes</h3><p>As notificações e alarmes dependem das permissões e configurações do Android. No Android, os alarmes usam agendamentos individuais do sistema, com som próprio e ações de parar e adiar. Lembretes podem ter alarme sonoro opcional. Notificações e alarmes exatos precisam de autorização. Funcionam com o aplicativo fechado, respeitando as restrições do Android e do fabricante. Parada forçada, revogação de permissão ou aparelho desligado impedem disparos. Os agendamentos são restaurados ao reiniciar o aparelho. O fuso é o do dispositivo.</p><h3>Cookies e funcionamento offline</h3><p>O aplicativo não cria cookies de publicidade ou análise. Usa armazenamento local essencial; os arquivos da interface já estão incluídos no APK para funcionar offline. Não há opções opcionais de rastreamento para aceitar.</p><h3>Exclusão e portabilidade</h3><p>Use Dados e preferências para exportar, restaurar ou apagar seus registros. O arquivo de backup contém dados pessoais: guarde-o com cuidado.</p><h3>Créditos</h3><p>Desenvolvido por João Victor. Composição e desenhos feitos para o projeto. Tipografia Open Sans, com <a href="fonts/LICENSE.txt" target="_blank" rel="noopener">licença original</a>. Os ícones Lucide são servidos pelo próprio aplicativo, com <a href="licenses/lucide.txt" target="_blank" rel="noopener">licença ISC e créditos</a>. Não há fotografias de terceiros.</p></div>`)}
function guide(){modal('Comece pelo que precisa de um lugar.',`<div class="guideart">${sunArt()}</div><p class="dialogintro">Crie um item e ele aparece na área certa. A tela Hoje reúne as tarefas, o próximo compromisso e os gastos do mês.</p><div class="guidesteps"><p><strong>1</strong><span>Use <b>Criar</b> para registrar uma tarefa, compromisso, gasto ou aviso.</span></p><p><strong>2</strong><span>Seus registros ficam neste aparelho. Exporte um backup para guardá-los ou trocar de aparelho.</span></p></div><div class="dialogactions">${btn('skipguide','Agora não','textbutton')}${btn('first','Criar meu primeiro item '+icon('arrow',16),'primary')}</div>`,'guidedialog')}
async function enableSound(){try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();await audio.resume();soundReady=audio.state==='running';if(!soundReady)throw Error();beep();toast('Som liberado. Mantenha a página aberta.');render()}catch{toast('O navegador não liberou o som. Verifique o volume e tente novamente.')}}
function beep(){if(!audio||audio.state!=='running')return;const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=660;g.gain.setValueAtTime(0,audio.currentTime);g.gain.linearRampToValueAtTime(.12,audio.currentTime+.04);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.65);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.7)}
async function notifyTest(){modal('Notificações do navegador',`<p class="dialogintro">Podem mostrar um aviso fora desta aba enquanto o site estiver aberto. Você pode recusar e continuar usando os avisos na tela.</p><p>Estado atual: <strong>${'Notification'in window?esc(Notification.permission):'Não suportado'}</strong></p><p class="formhint">Se estiver bloqueado, altere a permissão nas configurações do site no navegador. Não há avisos agendados no servidor.</p><div class="dialogactions">${btn('close','Voltar','textbutton')}${btn('grantnotification','Permitir e testar','primary')}</div>`)}
async function sendNotification(title,body){try{if('Notification'in window&&Notification.permission==='granted'){if(sw)await sw.showNotification(title,{body,tag:'meuritmo-lite'});else new Notification(title,{body})}}catch{toast('O sistema não exibiu a notificação. O aviso na tela continua disponível.')}}
function stopAlarm(){clearInterval(alarmTimer);alarmTimer=null;alarmCurrent=null;$('#alarmalert').hidden=true;const next=alertQueue.shift();if(next)setTimeout(()=>showAlarm(next.i,next.key),250)}
function showAlarm(i,key){if(alarmCurrent){alertQueue.push({i,key});toast('Outro aviso aguardando: '+i.title);return}alarmCurrent={i,key};$('#alarmalert').hidden=false;$('#alarmalert').innerHTML=`<div>${icon(types[i.type][1],26)}<span>${i.type==='alarm'?'ALARME':'LEMBRETE'}</span><h2>${esc(i.title)}</h2><p>${i.type==='alarm'&&!soundReady?'Som não liberado. Este é um aviso visual.':'Horário: '+esc(i.time)}</p></div><div>${btn('stopalarm','Entendi','primary')}${btn('snooze','Lembrar em 10 minutos','secondary')}</div>`;if(i.type==='alarm'&&soundReady){beep();let count=0;alarmTimer=setInterval(()=>{if(++count>=10){clearInterval(alarmTimer);alarmTimer=null;return}beep()},2000)}if(data.notifications)void sendNotification(i.title,'Meu Ritmo Lite · '+(i.time||'Agora'))}
function checkAlerts(){if(storageError||native)return;const now=new Date(),day=today(now),current=now.getHours()*60+now.getMinutes();for(const i of activeItems()){if(!i.enabled||(!['alarm','reminder'].includes(i.type)&&!i.notify)||!i.time||!occurs(i,day)||i.skip.includes(day)||done(i,day))continue;const [h,m]=i.time.split(':').map(Number),delta=current-(h*60+m),key=i.id+'@'+day+'@'+i.time;if(delta>=0&&delta<2&&!data.fired[key]){if(change(d=>{d.fired[key]=Date.now()}))showAlarm(i,key);break}}}
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){flushNote();close()}});$('#dialog').addEventListener('cancel',()=>flushNote());$('#dialog').addEventListener('close',()=>{flushNote();render()});
function flushNote(){if(!saveTimer||!$('#notebody'))return;clearTimeout(saveTimer);saveTimer=null;const id=$('#notebody').dataset.id;if(id)change(d=>{const i=d.items.find(x=>x.id===id);if(i&&i.body!==$('#notebody').value){i.body=$('#notebody').value;i.checked=[]}})}
function changeMonth(n){const d=new Date(date+'T12:00:00');d.setDate(1);d.setMonth(d.getMonth()+n);date=today(d);render()}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target)return;const {action,id,type}=target.dataset,day=target.dataset.date||date,i=data.items.find(i=>i.id===id);switch(action){case'quick':quick();break;case'nativestop':dismissNative(id);setTimeout(render,300);break;case'nativesnooze':dismissNative(id,true);setTimeout(render,300);break;case'nativepermissions':nativePermissions();break;case'nativetest':nativeTest();break;case'nativestatus':syncNative(data);setTimeout(()=>{render();toast('Estado dos agendamentos atualizado.')},350);break;case'calendar':if(i&&native){const form=$('#itemform');const f=form?new FormData(form):null;if(f&&['title','date','time','end','body'].some(k=>String(f.get(k)||'')!==String(i[k]||''))){toast('Salve as alterações antes de enviar ao calendário do celular.');break;}AndroidHost.calendar(JSON.stringify(i));}break;case'searchnotes':location.hash='notas';setTimeout(()=>$('#search')?.focus(),40);break;case'alerts':location.hash='lembretes';break;case'dayreview':reviewDay();break;case'new':editor(type,null,day);break;case'edit':if(i)editor(i.type,id);break;case'close':flushNote();close();break;case'guide':guide();break;case'skipguide':change(d=>d.guideDone=true);close();break;case'first':change(d=>d.guideDone=true);quick();break;case'more':modal('Mais do seu espaço',`<div class="quicktypes">${areas.filter(a=>['notas','lembretes','recados','alarmes'].includes(a[0])).map(([k,t,ic])=>`<a class="typebutton" href="#${k}" data-action="navclose">${icon(ic,24)}<span>${t}</span></a>`).join('')}</div>${btn('settings','Dados e preferências','secondary')}${btn('guide','Como usar','textbutton')}`);break;case'navclose':close();break;case'done':if(i&&change(d=>{const t=d.items.find(x=>x.id===id);t.completed=t.completed.includes(day)?t.completed.filter(v=>v!==day):[...t.completed,day]},{undo:true})){render();if($('#dialog').open&&$('#dialogtitle').textContent==='Passar o dia a limpo')reviewDay();toast(done(data.items.find(x=>x.id===id),day)?'Concluído.':'Tarefa reaberta.',true)}break;case'postpone':if(i&&confirm('Adiar “'+i.title+'” para amanhã? Só esta ocorrência será alterada.')){if(change(d=>{d.items.find(x=>x.id===id).skip.push(day);const task={...structuredClone(i),id:crypto.randomUUID(),date:addDays(day,1),repeat:'none',days:[],skip:[],completed:[]};d.items.push(task)},{undo:true})){render();toast('Adiado para amanhã.',true)}}break;case'up':case'down':if(i){change(d=>{const group=d.items.filter(x=>x.type==='task'&&occurs(x,date)&&!x.skip.includes(date)&&!!x.time===!!i.time),pos=group.findIndex(x=>x.id===id),other=group[pos+(action==='up'?-1:1)];if(!other)return;const a=d.items.findIndex(x=>x.id===id),b=d.items.findIndex(x=>x.id===other.id);[d.items[a],d.items[b]]=[d.items[b],d.items[a]]});render()}break;case'delete':if(i&&confirm('Excluir “'+i.title+'”'+(i.repeat!=='none'?' e todas as ocorrências da série':'')+'?')){if(change(d=>d.items=d.items.filter(x=>x.id!==id),{undo:true})){close();toast('Item excluído.',true)}}break;case'undo':if(undoState){const previous=structuredClone(undoState);undoState=null;previous.revision=data.revision;if(persist(previous)){render();toast('Ação desfeita.')}}break;case'pin':if(i){if(!i.pinned&&data.items.filter(x=>x.pinned&&!x.archived).length>=3){toast('Você pode fixar até três notas ou recados.');break}if(change(d=>d.items.find(x=>x.id===id).pinned=!i.pinned)){render();toast(i.pinned?'Item desafixado.':'Deixado à vista.')}}break;case'archive':if(i&&change(d=>{const item=d.items.find(x=>x.id===id);item.archived=!i.archived;if(item.archived)item.pinned=false},{undo:true})){render();toast(i.archived?'Item restaurado.':'Item arquivado.',true)}break;case'archived':archived=!archived;render();break;case'note':openNote(id);if($('#notebody'))$('#notebody').dataset.id=id;break;case'convert':if(i){flushNote();editor(type);$('#itemform [name=title]').value=i.title;$('#itemform [name=body]').value=i.body;toast('Revise a data e salve para criar. A nota original será mantida.')}break;case'enabled':if(i){change(d=>d.items.find(x=>x.id===id).enabled=!i.enabled);render()}break;case'view':view=target.dataset.view;render();break;case'prev':case'next':if(view==='month')changeMonth(action==='prev'?-1:1);else{date=addDays(date,(action==='prev'?-1:1)*(view==='week'?7:1));render()}break;case'today':date=today();render();break;case'day':date=day;view='day';render();break;case'routineday':date=day;render();break;case'routineprev':case'routinenext':date=addDays(date,action==='routineprev'?-7:7);render();break;case'prevmonth':case'nextmonth':changeMonth(action==='prevmonth'?-1:1);break;case'budget':{const month=date.slice(0,7);modal('Orçamento de '+new Date(month+'-01T12:00:00').toLocaleDateString('pt-BR',{month:'long'}),`<form id="budgetform"><label>Quanto você pretende gastar neste mês?<input name="amount" inputmode="decimal" required placeholder="Ex.: 2.000,00" value="${data.budgets[month]?(data.budgets[month]/100).toFixed(2).replace('.',','):''}"></label><p class="formhint">Vale apenas para ${new Date(date+'T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}. As despesas não são alteradas.</p><p id="budgeterror" role="alert" class="formerror"></p><div class="dialogactions"><span></span><button class="primary">Salvar orçamento</button></div></form>`);$('#budgetform').onsubmit=e=>{e.preventDefault();try{const amount=parseMoney(new FormData(e.target).get('amount'));if(change(d=>d.budgets[month]=amount)){close();toast('Orçamento salvo.')}}catch(err){$('#budgeterror').textContent=err.message}};break}case'review':{const month=area==='hoje'?today().slice(0,7):date.slice(0,7),bs=budgetStatus(data,month);modal('Dar contexto ao excesso',`<form id="reviewform"><p>Você registrou ${currency(bs.total)} para um orçamento de ${currency(bs.budget)}. A justificativa não reduz o total: apenas marca este excesso como revisado.</p><label>O que explica essa diferença?<textarea name="reason" required minlength="10" maxlength="1000" rows="4">${esc(data.reviews[month]?.reason||'')}</textarea></label><div class="dialogactions"><span></span><button class="primary">Registrar justificativa</button></div></form>`);$('#reviewform').onsubmit=e=>{e.preventDefault();const reason=new FormData(e.target).get('reason').trim();if(reason.length<10)return;if(change(d=>d.reviews[month]={reason,total:bs.total,budget:bs.budget})){close();toast('Excesso revisado. O valor continua visível.')}};break}case'unlinkappearance':try{localStorage.removeItem(THEME_LINK_KEY);localStorage.removeItem(THEME_CACHE_KEY);toast('Aparência desvinculada.');close();location.reload();}catch{toast('Não foi possível desvincular.')}break;case'settings':settings();break;case'backup':backup(storageError);break;case'restore':$('#restorefile').click();break;case'clear':modal('Apagar os dados deste aplicativo?',`<p>Serão excluídos todos os registros e cancelados os alarmes do Meu Ritmo Lite neste aparelho. Não é possível desfazer. <button data-action="backup" class="textbutton">Exporte um backup antes.</button></p><form id="clearform"><label>Digite APAGAR para confirmar<input required pattern="APAGAR" autocomplete="off" name="confirm"></label><div class="dialogactions">${btn('close','Cancelar','secondary','type="button"')}<button class="danger">Apagar definitivamente</button></div></form>`);$('#clearform').onsubmit=e=>{e.preventDefault();try{localStorage.removeItem(KEY);data=blank();syncNative(data);undoState=null;storageError=false;alertQueue=[];stopAlarm();close();toast('Dados locais apagados.')}catch{toast('O navegador não permitiu apagar os dados.')}};break;case'privacy':privacy();break;case'sound':await enableSound();break;case'notification':await notifyTest();break;case'grantnotification':if(!('Notification'in window)){toast('Este navegador não oferece notificações.');break}try{const permission=await Notification.requestPermission();change(d=>d.notifications=permission==='granted');if(permission==='granted'){await sendNotification('Meu Ritmo Lite','Este é um teste de notificação.');close();toast('Permissão concedida. Teste enviado ao sistema.')}else{toast('Sem permissão. Os avisos na tela continuam funcionando.');close()}}catch{toast('Não foi possível solicitar a permissão.')}break;case'stopalarm':if(alarmCurrent){const id=alarmCurrent.i.id;change(d=>{const i=d.items.find(x=>x.id===id);if(i&&!i.completed.includes(today()))i.completed.push(today())});}stopAlarm();render();break;case'snooze':if(alarmCurrent){const i=alarmCurrent.i,later=new Date(Date.now()+600000),copy={...structuredClone(i),id:crypto.randomUUID(),title:i.title,date:today(later),time:later.toTimeString().slice(0,5),repeat:'none',days:[],skip:[],completed:[]};if(change(d=>d.items.push(copy))){stopAlarm();toast('Novo aviso em dez minutos. Mantenha a página aberta.')}}break}});
document.addEventListener('change',e=>{if(e.target.id==='agendadate'&&validDate(e.target.value)){date=e.target.value;render()}if(e.target.id==='expensemonth'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(e.target.value)){date=e.target.value+'-01';render()}if(e.target.id==='routinedate'&&validDate(e.target.value)){date=e.target.value;render()}if(e.target.id==='repeat')$('#weekdays').hidden=e.target.value!=='weekly';if(e.target.id==='categoryfilter'){filter=e.target.value;render()}if(e.target.dataset.check){const id=e.target.dataset.id,index=Number(e.target.dataset.check);change(d=>{const i=d.items.find(x=>x.id===id);i.checked=i.checked.includes(index)?i.checked.filter(n=>n!==index):[...i.checked,index]})}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;const start=e.target.selectionStart;render();const input=$('#search');input.focus();input.setSelectionRange(start,start)}});
document.addEventListener('submit',async e=>{if(e.target.id!=='appearance-link-form')return;e.preventDefault();const token=new FormData(e.target).get('appearanceToken')?.toString().trim().toLowerCase()||'';if(!/^[a-f0-9]{64}$/.test(token)){toast('Chave inválida.');return;}try{const r=await fetch(THEME_URL,{headers:{Authorization:'Bearer '+token},cache:'no-store'});if(!r.ok)throw Error('Chave inválida ou conexão indisponível.');const t=await r.json();if(!applyAppearance(t))throw Error('Aparência inválida.');localStorage.setItem(THEME_LINK_KEY,token);localStorage.setItem(THEME_CACHE_KEY,JSON.stringify(t));close();toast('Aparência vinculada ao Meu Ritmo.');}catch(err){toast(err.message||'Não foi possível vincular.');}});
$('#restorefile').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{if(file.size>2_000_000)throw Error('O arquivo deve ter até 2 MB.');const imported=validateData(JSON.parse(await file.text()));if(!confirm(`Restaurar ${imported.items.length} itens? Todos os registros atuais serão substituídos. Exporte um backup antes de continuar.`))return;if(storageError){localStorage.setItem(KEY,JSON.stringify({...imported,revision:imported.revision+1}));data={...imported,revision:imported.revision+1};storageError=false;}else{imported.revision=data.revision;if(!persist(imported,{undo:true}))return}alertQueue=[];stopAlarm();close();syncNative(data);toast('Backup restaurado.',true)}catch(err){toast(err.message||'Não foi possível restaurar o backup.')}});
window.addEventListener('hashchange',()=>{const name=location.hash.slice(1);area=areas.some(a=>a[0]===name)?name:'hoje';search='';filter='Todos';archived=false;render();$('#main').focus();window.scrollTo({top:0,behavior:'instant'})});
window.addEventListener('storage',e=>{if(e.key===KEY){if($('#dialog').open){toast('Outra aba alterou seus dados. Copie seu texto e recarregue antes de salvar.');return}try{data=e.newValue?validateData(JSON.parse(e.newValue)):blank();render();toast('Dados atualizados por outra aba.')}catch{toast('Não foi possível ler as alterações da outra aba.')}}});
document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='n'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#dialog').open){e.preventDefault();quick()}});
window.addEventListener('beforeunload',()=>flushNote());document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flushNote();else checkAlerts()});
window.addEventListener('ritmo:native',e=>{const st=e.detail;let changed=false;for(const [id,day]of Object.entries(st.dismissed||{})){const i=data.items.find(i=>i.id===id);if(i&&validDate(day)&&!i.completed.includes(day))changed=true;}if(changed)change(d=>{for(const [id,day]of Object.entries(st.dismissed||{})){const i=d.items.find(i=>i.id===id);if(i&&validDate(day)&&!i.completed.includes(day))i.completed.push(day);}});if(!$('#dialog').open)render();});
if(areas.some(a=>a[0]===location.hash.slice(1)))area=location.hash.slice(1);render();if(!data.guideDone&&!storageError)setTimeout(guide,500);setInterval(checkAlerts,15000);setTimeout(checkAlerts,1500);

if(native)setTimeout(()=>syncNative(data),500);

let lastNativeActive='';if(native)setInterval(()=>{const s=nativeStatus(),key=JSON.stringify(s.active||[]);if(key!==lastNativeActive){lastNativeActive=key;if(!$('#dialog').open)render();}},3000);


